const flushPromises = () => new Promise((resolve) => setImmediate(resolve));

const instantiatePage = (config) => {
  const instance = {
    data: JSON.parse(JSON.stringify(config.data)),
    setData(update) {
      Object.assign(this.data, update);
    }
  };
  Object.entries(config)
    .filter(([key]) => key !== 'data')
    .forEach(([key, value]) => {
      if (typeof value === 'function') {
        instance[key] = value.bind(instance);
      } else {
        instance[key] = value;
      }
    });
  return instance;
};

describe('Story page interactions', () => {
  let pageConfig;
  let submitTurnTelemetry;
  const requestQueue = [];

  const enqueueResponse = (method, url, statusCode, data) => {
    requestQueue.push({ method, url, statusCode, data });
  };

  const loadPage = () => {
    jest.isolateModules(() => {
      require('../index.js');
    });
  };

  beforeEach(() => {
    jest.resetModules();
    jest.clearAllMocks();
    pageConfig = null;
    requestQueue.length = 0;

    global.wx.request.mockImplementation(({ url, method = 'GET', success, fail }) => {
      const next = requestQueue.shift();
      if (!next) {
        fail?.(new Error(`No mock for ${method} ${url}`));
        return;
      }
      expect({ method, url }).toEqual({ method: next.method, url: next.url });
      success({ statusCode: next.statusCode, data: next.data });
    });

    global.wx.showToast.mockClear();
    global.Page = (config) => {
      pageConfig = config;
    };

    loadPage();
    submitTurnTelemetry = jest.requireMock('../../utils/telemetry').submitTurnTelemetry;
  });

  afterEach(() => {
    delete global.Page;
    global.wx.request.mockReset();
  });

  it('initializes story session and progresses turns', async () => {
    enqueueResponse('POST', '/stories', 200, {
      sessionId: 'session-1',
      narrative: '序章',
      options: ['A', 'B', 'C', 'D'],
      ending: false
    });
    enqueueResponse('POST', '/stories/session-1/turns', 200, {
      sessionId: 'session-1',
      turnIndex: 1,
      narrative: '第二段',
      options: ['A1', 'B1', 'C1', 'D1'],
      ending: false,
      moderationMessage: ''
    });

    const page = instantiatePage(pageConfig);

    await page.onLoad({ themeId: 'school-revenge' });
    await flushPromises();

    expect(page.data.sessionId).toBe('session-1');
    expect(page.data.narrative).toBe('序章');
    expect(page.data.options).toHaveLength(4);
    expect(page.data.turnCount).toBe(1);

    await page.onSelectOption({ currentTarget: { dataset: { index: 1 } } });
    await flushPromises();

    expect(page.data.narrative).toBe('第二段');
    expect(page.data.options[0]).toBe('A1');
    expect(page.data.turnCount).toBe(2);
  });

  it('handles ending state and shows toast on error', async () => {
    enqueueResponse('POST', '/stories', 200, {
      sessionId: 'session-1',
      narrative: '终章',
      options: [],
      ending: true
    });

    const page = instantiatePage(pageConfig);
    await page.onLoad({ themeId: 'school-revenge' });
    await flushPromises();

    expect(page.data.ending).toBe(true);
    expect(page.data.turnCount).toBe(1);

    // ensure no advance when ending
    await page.onSelectOption({ currentTarget: { dataset: { index: 0 } } });
    enqueueResponse('POST', '/stories/session-1/turns', 500, {});
    page.setData({ sessionId: 'session-1', ending: false });
    await page.advanceStory(1);
    expect(global.wx.showToast).toHaveBeenCalledWith({ title: '加载失败，请重试', icon: 'none' });
  });

  it('starts story when pending theme is set via tab switch', async () => {
    enqueueResponse('POST', '/stories', 200, {
      sessionId: 'session-2',
      narrative: '开场',
      options: ['A', 'B', 'C', 'D'],
      ending: false
    });

    const page = instantiatePage(pageConfig);
    const app = getApp();
    app.globalData.pendingThemeId = 'school-revenge';

    await page.onShow();
    await flushPromises();

    expect(page.data.themeId).toBe('school-revenge');
    expect(page.data.sessionId).toBe('session-2');
    expect(page.data.turnCount).toBe(1);
    expect(app.globalData.pendingThemeId).toBe('');
  });

  it('refresh button restarts current story', async () => {
    enqueueResponse('POST', '/stories', 200, {
      sessionId: 'session-1',
      narrative: '开场',
      options: ['A', 'B', 'C', 'D'],
      ending: false
    });

    const page = instantiatePage(pageConfig);
    await page.onLoad({ themeId: 'school-revenge' });
    await flushPromises();

    enqueueResponse('POST', '/stories', 200, {
      sessionId: 'session-3',
      narrative: '重新开始',
      options: ['A', 'B', 'C', 'D'],
      ending: false
    });

    page.onRefresh();
    await flushPromises();

    expect(page.data.sessionId).toBe('session-3');
    expect(page.data.turnCount).toBe(1);
  });
});
