{"output":"import { api } from '../../utils/api';
import { submitTurnTelemetry } from '../../utils/telemetry';

Page({
  currentModelProvider: 'qwen',
  data: {
    themeId: '',
    sessionId: '',
    narrative: '',
    options: [],
    ending: false,
    moderationMessage: '',
    isLoading: false,
    turnCount: 0
  },

  onLoad(query) {
    const { themeId } = query;
    if (themeId) {
      this.setData({ themeId });
      void this.startStory(themeId);
      const app = getApp();
      if (app && app.globalData) {
        app.globalData.pendingThemeId = '';
      }
    }
  },

  onShow() {
    this.setTabBarIndex(0);
    const app = getApp();
    const pending = app?.globalData?.pendingThemeId;
    if (pending && pending !== this.data.themeId) {
      this.setData({ themeId: pending });
      app.globalData.pendingThemeId = '';
      void this.startStory(pending);
    }
  },

  async startStory(themeId) {
    this.setData({ isLoading: true, moderationMessage: '', turnCount: 0 });
    try {
      const app = getApp();
      const modelProvider = app?.globalData?.preferredModel || this.currentModelProvider || 'qwen';
      this.currentModelProvider = modelProvider;
      const response = await api.startStory({ themeId, modelProvider });
      this.setData({
        sessionId: response.sessionId,
        narrative: response.narrative,
        options: response.options ?? [],
        ending: response.ending ?? false,
        isLoading: false,
        turnCount: typeof response.turnIndex === 'number' ? response.turnIndex + 1 : 1
      });
      this.scrollToTop();
    } catch (error) {
      this.handleError(error);
    }
  },

  async onSelectOption(event) {
    const { index } = event.currentTarget.dataset;
    const selectedOption = Number(index) + 1;
    await this.advanceStory(selectedOption);
  },

  async advanceStory(selectedOption) {
    if (this.data.ending || !this.data.sessionId) {
      return;
    }

    this.setData({ isLoading: true, moderationMessage: '' });
    try {
      const modelProvider = this.currentModelProvider || getApp()?.globalData?.preferredModel;
      const response = await api.advanceStory({
        sessionId: this.data.sessionId,
        selectedOption,
        modelProvider
      });

      void submitTurnTelemetry({
        sessionIdHash: this.data.sessionId,
        themeId: this.data.themeId,
        turnIndex: response.turnIndex,
        latencyMs: response.latencyMs ?? 0,
        outcome: response.outcome || (response.ending ? 'success' : 'success'),
        timestamp: new Date().toISOString()
      });

      this.setData({
        narrative: response.narrative,
        options: response.options ?? [],
        ending: response.ending ?? false,
        moderationMessage: response.moderationMessage ?? '',
        isLoading: false,
        turnCount:
          typeof response.turnIndex === 'number'
            ? response.turnIndex + 1
            : this.data.turnCount + 1
      });
      this.scrollToTop();

      if (response.ending) {
        this.setData({ sessionId: '' });
      }
    } catch (error) {
      this.handleError(error);
    }
  },

  scrollToTop() {
    if (typeof wx?.pageScrollTo === 'function') {
      wx.pageScrollTo({ scrollTop: 0, duration: 0 });
    }
  },

  handleError(error) {
    console.warn('Story error', error);
    this.setData({ isLoading: false });
    wx.showToast({ title: '加载失败，请重试', icon: 'none' });
  },

  async onRestart() {
    if (this.data.themeId) {
      await this.startStory(this.data.themeId);
    }
  },

  onRefresh() {
    if (this.data.isLoading || !this.data.themeId) {
      return;
    }
    void this.startStory(this.data.themeId);
  },

  onReturnHome() {
    wx.switchTab({ url: '/pages/catalog/index' });
  },

  setTabBarIndex(index) {
    if (typeof this.getTabBar === 'function') {
      const tabBar = this.getTabBar();
      if (tabBar && typeof tabBar.setSelected === 'function') {
        tabBar.setSelected(index);
      }
    }
  }
});
